INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES (3, 5, 'Why Workplace Safety Matters', 'text', '<h3>Introduction</h3><p>A safe workplace protects people, productivity, and reputation. This lesson explains the business and human reasons behind workplace safety.</p>', NULL, 1, 'active', '2026-10-15 21:24:54', '2026-10-15 21:24:54');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES (4, 5, 'Roles, Rights, and Responsibilities', 'text', '<h3>Everyone Has a Role</h3><p>Understand employee rights, employer duties, and how to report concerns through the correct channels.</p>', NULL, 2, 'active', '2026-10-15 21:24:54', '2026-10-15 21:24:54');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES (5, 6, 'Spotting Common Workplace Hazards', 'text', '<h3>Hazard Awareness</h3><p>Learn how to identify physical, ergonomic, chemical, and psychosocial hazards before they cause harm.</p>', NULL, 1, 'active', '2026-10-15 21:24:54', '2026-10-15 21:24:54');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES (6, 6, 'The Hierarchy of Risk Controls', 'text', '<h3>Controlling Risk</h3><p>Elimination, substitution, engineering controls, administrative controls, and PPE - applied in the right order.</p>', NULL, 2, 'active', '2026-10-15 21:24:54', '2026-10-15 21:24:54');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES (7, 7, 'The Communication Process', 'text', '<h3>Sender, Message, Receiver</h3><p>Explore the communication loop and the barriers that cause misunderstandings at work.</p>', NULL, 1, 'active', '2026-10-15 21:24:54', '2026-10-15 21:24:54');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES (8, 7, 'Active Listening Techniques', 'video', NULL, 'https://www.youtube.com/embed/1Y9d3lR6Qm4', 2, 'active', '2026-10-15 21:24:54', '2026-10-15 21:24:54');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES (9, 8, 'Writing Clear Emails and Reports', 'text', '<h3>Write to Be Understood</h3><p>Structure business messages with a clear purpose, audience, and call to action.</p>', NULL, 1, 'active', '2026-10-15 21:24:54', '2026-10-15 21:24:54');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES (10, 8, 'Delivering Confident Presentations', 'video', NULL, 'https://www.youtube.com/embed/AykYRO5d_lI', 2, 'active', '2026-10-15 21:24:54', '2026-10-15 21:24:54');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES (11, 9, 'Navigating Excel and Key Functions', 'text', '<h3>Excel Basics</h3><p>Work with cells, ranges, formulas, and lookup functions that form the backbone of analysis.</p>', NULL, 1, 'active', '2026-10-15 21:24:54', '2026-10-15 21:24:54');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES (12, 9, 'Cleaning and Organizing Data', 'text', '<h3>From Messy to Tidy</h3><p>Remove duplicates, standardize values, and structure data for reliable reporting.</p>', NULL, 2, 'active', '2026-10-15 21:24:54', '2026-10-15 21:24:54');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES (13, 10, 'Building Charts and Pivot Tables', 'video', NULL, 'https://www.youtube.com/embed/xbLcfBGU5Qc', 1, 'active', '2026-10-15 21:24:54', '2026-10-15 21:24:54');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES (14, 10, 'Presenting Insights from Data', 'text', '<h3>Telling the Story</h3><p>Choose the right chart and highlight the insight that drives a decision.</p>', NULL, 2, 'active', '2026-10-15 21:24:54', '2026-10-15 21:24:54');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES (15, 11, 'From Team Member to Team Lead', 'text', '<h3>A New Perspective</h3><p>Shift from doing the work to enabling the team to do the work.</p>', NULL, 1, 'active', '2026-10-15 21:24:54', '2026-10-15 21:24:54');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES (16, 11, 'Setting Expectations and Goals', 'text', '<h3>Clarity Drives Performance</h3><p>Define outcomes, agree on measures, and align the team around shared goals.</p>', NULL, 2, 'active', '2026-10-15 21:24:54', '2026-10-15 21:24:54');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES (17, 12, 'Giving Constructive Feedback', 'video', NULL, 'https://www.youtube.com/embed/6z4g7w2KqEo', 1, 'active', '2026-10-15 21:24:54', '2026-10-15 21:24:54');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES (18, 12, 'Running One-on-One Meetings', 'text', '<h3>Make Time Count</h3><p>A repeatable agenda for check-ins that develop people and surface issues early.</p>', NULL, 2, 'active', '2026-10-15 21:24:54', '2026-10-15 21:24:54');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES (19, 13, 'Understanding Customer Expectations', 'text', '<h3>What Customers Want</h3><p>Responsiveness, reliability, empathy, and a resolution - every time.</p>', NULL, 1, 'active', '2026-10-15 21:24:54', '2026-10-15 21:24:54');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES (20, 13, 'Building Rapport and Empathy', 'text', '<h3>Connect First</h3><p>Simple techniques to make customers feel heard and valued.</p>', NULL, 2, 'active', '2026-10-15 21:24:54', '2026-10-15 21:24:54');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES (21, 14, 'De-escalation Techniques', 'video', NULL, 'https://www.youtube.com/embed/1EvUCfXWLoU', 1, 'active', '2026-10-15 21:24:54', '2026-10-15 21:24:54');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES (22, 14, 'Resolving Complaints Effectively', 'text', '<h3>From Complaint to Resolution</h3><p>A structured approach to acknowledge, investigate, and resolve complaints.</p>', NULL, 2, 'active', '2026-10-15 21:24:54', '2026-10-15 21:24:54');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES (23, 15, 'Common Cyber Threats Explained', 'text', '<h3>Know the Threats</h3><p>Malware, ransomware, social engineering, and insider risk explained in plain language.</p>', NULL, 1, 'active', '2026-10-15 21:24:54', '2026-10-15 21:24:54');
